#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int kernel_height,
    int kernel_width,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int output_height,
    int output_width
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_h_idx = blockIdx.z;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_h_idx >= output_height) {
        return;
    }

    int tid = threadIdx.x;
    int total_threads = blockDim.x;

    // Each thread processes multiple output pixels
    for (int out_w_idx = tid; out_w_idx < output_width; out_w_idx += total_threads) {
        // Initialize accumulator with zero
        float sum = 0.0f;

        // Loop over input channels and kernel elements
        for (int in_ch = 0; in_ch < in_channels; ++in_ch) {
            for (int kh = 0; kh < kernel_height; ++kh) {
                for (int kw = 0; kw < kernel_width; ++kw) {
                    // Calculate input position
                    int ih = out_h_idx * stride_h + kh - pad_h;
                    int iw = out_w_idx * stride_w + kw - pad_w;

                    // Check bounds
                    if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                        // Calculate indices
                        int input_idx = batch_idx * (in_channels * input_height * input_width) +
                                       in_ch * (input_height * input_width) +
                                       ih * input_width + iw;

                        int weight_idx = out_ch_idx * (in_channels * kernel_height * kernel_width) +
                                        in_ch * (kernel_height * kernel_width) +
                                        kh * kernel_width + kw;

                        // Accumulate
                        sum += (float)input[input_idx] * (float)weight[weight_idx];
                    }
                }
            }
        }

        // Write result
        int output_idx = batch_idx * (out_channels * output_height * output_width) +
                        out_ch_idx * (output_height * output_width) +
                        out_h_idx * output_width + out_w_idx;

        output[output_idx] = __float2half(sum);
    }
}

// Wrapper function to launch kernel
extern "C" void launch_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int kernel_height,
    int kernel_width,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int output_height,
    int output_width
) {
    dim3 grid(batch_size, out_channels, output_height);
    dim3 block(256);  // 256 threads per block

    conv2d_kernel<<<grid, block>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_height, input_width,
        kernel_height, kernel_width,
        stride_h, stride_w,
        pad_h, pad_w,
        output_height, output_width
    );

    cudaDeviceSynchronize();
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = torch.nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

        # Load the CUDA extension
        self.conv2d_kernel = load_inline(
            name="conv2d_kernel",
            cpp_sources="",
            cuda_sources=cuda_source,
            functions=["launch_conv2d"],
            verbose=False
        )

    def forward(self, x):
        # Get parameters from the original conv layer
        weight = self.conv1.weight.data.contiguous()
        bias = self.conv1.bias.data.contiguous() if self.conv1.bias is not None else None

        # Prepare input for CUDA kernel
        batch_size, _, height, width = x.shape
        out_channels, in_channels, kernel_h, kernel_w = weight.shape
        stride_h, stride_w = self.conv1.stride
        pad_h, pad_w = self.conv1.padding
        output_h = (height + 2 * pad_h - kernel_h) // stride_h + 1
        output_w = (width + 2 * pad_w - kernel_w) // stride_w + 1

        # Allocate output tensor
        output = torch.empty(
            batch_size, out_channels, output_h, output_w,
            dtype=torch.float16, device=x.device
        )

        # Launch CUDA kernel
        self.conv2d_kernel.launch_conv2d(
            x.contiguous().data_ptr(),
            weight.contiguous().data_ptr(),
            output.data_ptr(),
            batch_size,
            in_channels,
            out_channels,
            height,
            width,
            kernel_h,
            kernel_w,
            stride_h,
            stride_w,
            pad_h,
            pad_w,
            output_h,
            output_w
        )

        # Add bias if present
        if bias is not None:
            output = output + bias.view(1, -1, 1, 1)

        return output

